import{bT as s,aL as a,u as t,G as i}from"./chunks/framework.CbRBFYqW.js";const o="/images/unlock_network/1.png",l="/images/unlock_network/2.png",n="/images/unlock_network/3.png",c="/images/unlock_network/4.png",p="/images/unlock_network/5.png",r="/images/unlock_network/6.png",d="/images/unlock_network/7.png",u="/images/unlock_network/8.png",m="/images/unlock_network/9.png",y=JSON.parse('{"title":"网络解锁教程","description":"手动解锁噢易学生端网络限制","frontmatter":{"outline":"deep","title":"网络解锁教程","date":"2025-06-22T21:10:00.000Z","permalink":"/guide/unlock_network","categories":["指南"],"tags":["教程"],"description":"手动解锁噢易学生端网络限制"},"headers":[],"relativePath":"01.指南/01.简介/02.网络解锁.md","filePath":"01.指南/01.简介/02.网络解锁.md"}'),h={name:"01.指南/01.简介/02.网络解锁.md"};function g(b,e,k,_,v,q){return a(),t("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /01.指南/01.简介/02.网络解锁.md for this page in Markdown format</div><h1 id="🌐-如何手动解锁网络限制" tabindex="-1">🌐 如何手动解锁网络限制 <a class="header-anchor" href="#🌐-如何手动解锁网络限制" aria-label="Permalink to &quot;🌐 如何手动解锁网络限制&quot;">​</a></h1><blockquote><p>即使不下载 OsEasy-ToolKit 工具，你也可以手动输入几条命令来解锁噢易学生端的网络限制。本教程手把手教你操作。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>在信息课上，学生端电脑被牢逝限制了网络</li><li>想了解解锁网络的底层原理</li><li>仅需恢复上网功能，不需要解锁其他限制</li></ul><div class="info custom-block"><p class="custom-block-title">一：打开 CMD（命令提示符）</p><p><strong>操作步骤：</strong></p><ol><li>点击任务栏搜索按钮，打开搜索菜单 <img src="'+o+'" alt="搜索 cmd" loading="lazy"></li><li>输入 <code>cmd</code>，在搜索结果中找到&quot;命令提示符&quot;，右键点击&quot;命令提示符&quot; → 选择&quot;以管理员身份运行&quot;，点击&quot;是&quot;确认 <img src="'+l+'" alt="以管理员身份运行" loading="lazy"></li><li>出现 CMD 黑色窗口即成功 <img src="'+n+'" alt="CMD 成功打开" loading="lazy"></li></ol><blockquote><p>Tips：机房电脑通常默认登录管理员账户，你也可以直接 Win+R 运行 cmd ，无需额外操作。</p></blockquote></div><div class="info custom-block"><p class="custom-block-title">二：停止 MMPC（学生端根服务）</p><div class="language-batch vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop mmpc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>停止学生端根服务（MMPC），这是管控学生端的中心服务（该服务没什么实质性的管控，但会实时监控学生端是否被偷偷关闭，若检测到学生端被关闭，就会自动重启相关进程。所以这是解锁的第一步）</p><p><strong>操作示例：</strong></p><ol><li>在 CMD 中输入命令 <code>sc stop mmpc</code> 并回车 <img src="'+c+'" alt="输入 sc stop mmpc" loading="lazy"></li><li>显示 <code>SEVER_NAME xxxxxxx</code> 即表示执行成功。命令不区分大小写 <img src="'+p+'" alt="执行成功" loading="lazy"></li></ol></div><div class="info custom-block"><p class="custom-block-title">三：停止 OeNetlimit（网络限制服务）</p><div class="language-batch vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop oenetlimit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>停止网络过滤和限制服务，解除驱动级服务对网络的限制。</p><p><strong>操作示例：</strong></p><ol><li><p>在 CMD 窗口中输入 <code>sc stop oenetlimit</code> 并回车</p><p><img src="'+r+'" alt="输入 sc stop oenetlimit" loading="lazy"></p></li><li><p>显示 <code>STATE: 1 STOPPED</code>（或 <code>STOP_PENDING</code>）即表示执行成功</p></li></ol></div><div class="info custom-block"><p class="custom-block-title">四：结束 DeviceControl_x64.exe（设备控制进程）</p><p>结束设备控制进程，解除网络和程序限制</p><p><strong>操作示例：</strong></p><ol><li>右键任务栏空白处 → 选择&quot;任务管理器&quot; <img src="'+d+'" alt="右键任务栏打开任务管理器" loading="lazy"></li><li>会弹出一个新的白色窗口，点击窗口左下角的&quot;详细信息&quot;展开完整列表 <img src="'+u+'" alt="点击详细信息" loading="lazy"></li><li>在进程列表中找到 <code>DeviceControl_x64.exe</code> → 右键 → 选择&quot;结束任务&quot; <img src="'+m+'" alt="结束进程" loading="lazy"></li></ol></div><p>总共就 **4 个步骤 **，逐步进行即可，熟练的话十几秒就能搞定。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">关闭服务时报错</p><h3 id="q-执行-sc-stop-提示服务名无效" tabindex="-1">Q：执行 <code>sc stop </code> 提示服务名无效？ <a class="header-anchor" href="#q-执行-sc-stop-提示服务名无效" aria-label="Permalink to &quot;Q：执行 `sc stop ` 提示服务名无效？&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[SC] OpenService FAILED 1060: 指定的服务未安装。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这说明你输错了，重新输。</p><h3 id="q-执行-sc-stop-提示服务未启动" tabindex="-1">Q：执行 <code>sc stop </code> 提示服务未启动？ <a class="header-anchor" href="#q-执行-sc-stop-提示服务未启动" aria-label="Permalink to &quot;Q：执行 `sc stop ` 提示服务未启动？&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[SC] OpenService FAILED 1060: 指定的服务未启动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这说明你输重复了，已经执行成功过了，请去执行下一步吧。</p></div><h3 id="q-重启电脑后网络又被限制了" tabindex="-1">Q：重启电脑后网络又被限制了？ <a class="header-anchor" href="#q-重启电脑后网络又被限制了" aria-label="Permalink to &quot;Q：重启电脑后网络又被限制了？&quot;">​</a></h3><p>这是正常的——学校机房将计算机设为了每次重启时还原，也就是说每次重启都不会保留你的任何内容，我也没办法，只能每次上课时进行解锁</p><h3 id="q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" tabindex="-1">Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？ <a class="header-anchor" href="#q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" aria-label="Permalink to &quot;Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？&quot;">​</a></h3><p>这是正常现象。学生端网络限制解除后，系统网络状态指示可能需要一段时间才能刷新。<strong>请直接打开浏览器访问任意网站</strong>，你会发现网络实际上已经恢复正常了，不需要理会网络图标的显示状态。</p>',16)])])}const f=s(h,[["render",g]]);export{y as __pageData,f as default};
